export function init(value) {
    let found = 0;
    for (const n of ['first','second','third','late']) { try { if (thisScene.getLayer(n)) found++; } catch (e) {} }
    let count = -1;
    try { count = thisScene.getLayerCount(); } catch (e) {}
    return new Vec3(300 + 10 * count, 200 + 100 * found, 0);
}
